local config = {
  ui_story_32040401_1_dialog_content = "Déjame contarlos por última vez. Uno, dos, tres... ¡Sí, son todos!",
  ui_story_32040401_2_dialog_content = "Hay todo tipo de cosas aquí de todo el mundo. Illumina, el desierto de Reddiesel... ¡Aquí hay incluso cosas de Longzhou!",
  ui_story_32040401_3_dialog_content = "May Pregunto para qué sirven todas estas cosas, señora. Joshua?",
  ui_story_32040401_4_dialog_content = "Oh, estos son solo <color=#FFB400>regalos</color> que recogí durante mis viajes.",
  ui_story_32040401_5_dialog_content = "Desde que dejé Lumopolis, me he encontrado con todo tipo de cosas nuevas y maravillosas.",
  ui_story_32040401_6_dialog_content = "Durante una visita reciente a Northland, aprendí cuán aisladas y reservadas pueden ser las personas en esta nación.",
  ui_story_32040401_7_dialog_content = "Y así, comencé a buscar una manera de compartir mis emocionantes experiencias con los niños.",
  ui_story_32040401_8_dialog_content = "¿Has estado reuniendo regalos de todo el mundo solo para ellos?",
  ui_story_32040401_9_dialog_content = "En efecto. Rezo para que mis regalos despierten su curiosidad juvenil y les den una idea de la verdadera inmensidad de nuestro mundo.",
  ui_story_32040401_10_dialog_content = "En las implacables arenas del desierto de Rediesel, un grupo de aurorianos descubrió una manera de sobrevivir juntos gracias a las virtudes de la lealtad y el compañerismo.",
  ui_story_32040401_11_dialog_content = "Y en la Federación Illumina, un único muro se alza entre un campo de batalla devastado por la guerra y una vida sencilla pero satisfactoria.",
  ui_story_32040401_12_dialog_content = "En Twin Pavilions Bay, incluso conocí a un viajero proveniente de Longzhou, una tierra que se encuentra al otro lado del océano. Su cultura e historia difieren tanto de la de Astra...",
  ui_story_32040401_13_dialog_content = "Si estos niños pueden comprender el gran tamaño de nuestro mundo, tal vez tengan aún más que esperar en esta vida.",
  ui_story_32040401_14_dialog_content = "Se pensó tanto en tan pequeños regalos... Eres increíble, Lady Joshua!",
  ui_story_32040401_15_dialog_content = "Jajaja, yo no iría tan lejos. Además, esto puede ayudarme a compensar algunos de <color=#FFB400>mi pasado se arrepiente</color>.",
  ui_story_32040401_16_dialog_content = "Mis disculpas por la demora, señora Joshua-¿Mmm? Qué sorpresa verte aquí también, PlayerName.",
  ui_story_32040401_17_dialog_content = "Hola, Novio! Así que eres la persona señora Joshua ¡estaba esperando a!",
  ui_story_32040401_18_dialog_content = "En efecto. Señor. Novio ha accedido amablemente a ayudarme a reunir a los niños, para que pueda repartir sus regalos.",
  ui_story_32040401_19_dialog_content = "No pienses en ello.",
  ui_story_32040401_20_dialog_content = "<size=33>Hace Novio saber de su situación, Señora Joshua?</size>",
  ui_story_32040401_21_dialog_content = "<size=33>Todavía no ha hecho ninguna mención al respecto, aunque estoy seguro de que ya debe tener alguna idea.</size>",
  ui_story_32040401_22_dialog_content = "Los niños están listos y esperando, mis amigos. Podemos irnos una vez que cargue los regalos en el carruaje.",
  ui_story_32040401_23_dialog_content = "¡Guau! ¡Tantos regalos!",
  ui_story_32040401_24_dialog_content = "¿Es este un instrumento de Longzhou? Nunca había visto algo así antes...",
  ui_story_32040401_25_dialog_content = "¡Una máquina de juegos de Illumina! ¡Quiero ése!",
  ui_story_32040401_26_dialog_content = "Cálmense, niños. Hay un montón de regalos para todos.",
  ui_story_32040401_27_dialog_content = "Uf... Eso fue mucho más agotador de lo que pensé que sería. ¡No tenía idea de que habría tantos niños!",
  ui_story_32040401_28_dialog_content = "Su arduo trabajo es muy apreciado. ¿Puedo ofrecerle un refresco?",
  ui_story_32040401_29_dialog_content = "¡Seguro! Y gracias de nuevo por quedarte, Novio. no creo señora Joshua y podría haberme encargado de todos esos niños sin tu ayuda.",
  ui_story_32040401_30_dialog_content = "Somos iguales en ese aspecto, ¿no es así? Entendí que solo estabas destinado a ayudar con el transporte de los regalos, pero elegiste quedarte y ayudarnos.",
  ui_story_32040401_31_dialog_content = "Bueno, no podía irme sin ofrecerme a ayudar; ella es una buena amiga después de todo. Además, ¡era por una buena causa!",
  ui_story_32040401_32_dialog_content = "Aún así, no esperaba que ayudaras a Lady Joshua con la promoción de culturas de fuera de Northland.",
  ui_story_32040401_33_dialog_content = "Ella simplemente desea enriquecer las vidas de nuestros niños pequeños ampliando sus horizontes. Sus motivos son puros, de eso no tengo ninguna duda.",
  ui_story_32040401_34_dialog_content = "No solo eso... Reina Bethlehem una vez tuvo una hermana mayor que se casó con un ex gobernador de Lumopolis y dejó Northland para estar con él.",
  ui_story_32040401_35_dialog_content = "¿Un ex gobernador de Lumopolis?",
  ui_story_32040401_36_dialog_content = "Tal vez... ¿O tal vez fue el anterior? Mi recuerdo es algo confuso. En ese momento, yo no era más que un mero espíritu de la montaña, y apenas me preocupaban los asuntos de gobierno.",
  ui_story_32040401_37_dialog_content = "Todo lo que recuerdo es la mirada de soledad en su rostro cuando salió del palacio.",
  ui_story_32040401_38_dialog_content = "Así como... La expresión de la Reina Belén cuando sus restos fueron enviados de regreso para ser enterrados.",
  ui_story_32040401_39_dialog_content = "En ese entonces, no pude ayudar a la pobre señora, y ahora... Ah, por favor perdóname. No debería molestarte con cosas tan aburridas del pasado.",
  ui_story_32040401_40_dialog_content = "(Aun asi Novio tiene su propia cuota de remordimientos, eh...)",
  ui_story_32040401_41_dialog_content = "¿Disculpe? ¿Fuisteis vosotros los que nos trajisteis todos estos regalos?",
  ui_story_32040401_42_dialog_content = "¿Eh? ¡Por qué sí, lo hicimos! Si quieres uno, ve a hablar con la simpática señora de cabello blanco que está allí.",
  ui_story_32040401_43_dialog_content = "No quiero ningún regalo. Solo quiero hacerte una pregunta.",
  ui_story_32040401_44_dialog_content = "¿Por qué te tomaste la molestia de traernos regalos del mundo exterior? ¿Tú qué sacas de esto?",
  ui_story_32040401_45_dialog_content = "¿Y por qué los ayudas, Señor? Novio? ¿No dijiste que Northland es el último paraíso que les queda a los aurorianos...?",
  ui_story_32040401_46_dialog_content = "(Oh, qué pregunta más directa... ¿qué le pasó a esta niña?)",
  ui_story_32040401_47_dialog_content = "Dios mío, esto no otra vez... Por favor, no te ofendas. PlayerName.",
  ui_story_32040401_48_dialog_content = "Este niño sueña con convertirse en caballero para proteger todo Northland. Ha demostrado ser bastante dotada para una niña de su edad.",
  ui_story_32040401_49_dialog_content = "Sin embargo, todavía tiene espacio para crecer con respecto a la comunicación interpersonal. Me disculpo si sus preguntas fueron demasiado directas.",
  ui_story_32040401_50_dialog_content = "En cuanto a ti, hijo mío, ten por seguro que PlayerName y dama Joshua no nos guardes mala voluntad en lo más mínimo.",
  ui_story_32040401_51_dialog_content = "Ahora ven, discúlpate con nuestros invitados.",
  ui_story_32040401_52_dialog_content = "... Lo siento.",
  ui_story_32040401_53_dialog_content = "Escucha atentamente, pequeña. Si realmente deseas defender Northland como un caballero al servicio de la reina, debes aprender a tratar a los demás con cortesía y consideración.",
  ui_story_32040401_54_dialog_content = "Si bien su honestidad y sinceridad son encomiables, ser demasiado directo a veces puede crear más problemas, tanto para usted como para las personas que ama.",
  ui_story_32040401_55_dialog_content = "¿Estás diciendo que no debería decir la verdad?",
  ui_story_32040401_56_dialog_content = "No niña, eso ciertamente no es lo que quise decir... Te pido que te abstengas de torcer mis palabras de esa manera.",
  ui_story_32040401_57_dialog_content = "(Jajaja... Supongo que esto es lo que quieren decir con inocencia infantil, ¿eh?)",
  ui_story_32040401_58_dialog_content = "...",
  ui_story_32040401_59_dialog_content = "No quise molestar Señor Novio. Pero no entiendo por qué no puedo decir lo que realmente pienso todo el tiempo...",
  ui_story_32040401_60_dialog_content = "Hola querido.",
  ui_story_32040401_61_dialog_content = "¡E-Eres tú! ¡¿Qué estás tramando exactamente?!",
  ui_story_32040401_62_dialog_content = "<size=33>Espera, no... Señor Novio dijo que tengo que tratar a los demás con cortesía.</size>",
  ui_story_32040401_63_dialog_content = "... Gracias por traernos regalos.",
  ui_story_32040401_64_dialog_content = "No tienes que agradecerme, pequeña. Después de todo, todavía no has recibido un regalo.",
  ui_story_32040401_65_dialog_content = "¿Y no es esa la verdad de la que hablas?",
  ui_story_32040401_66_dialog_content = "¿Eh? ¡¿C-Cómo lo supiste?!",
  ui_story_32040401_67_dialog_content = "Jejeje, está escrito en tu adorable carita.",
  ui_story_32040401_68_dialog_content = "Emm... ¡B-Bueno, no puedo evitarlo! ¡Es todo porque no entiendo!",
  ui_story_32040401_69_dialog_content = "Caballero Novio dijo que los Aurorianos fuera de Northland no podían unirse bajo una sola causa, y es por eso que los Eclipsites deambulan por toda la tierra.",
  ui_story_32040401_70_dialog_content = "¡¿Pero esos adultos todavía te piden que vengas aquí y nos cuentes lo divertido que es allá afuera?!",
  ui_story_32040401_71_dialog_content = "¿N-No significa eso que solo está dejando que nos engañes...?",
  ui_story_32040401_72_dialog_content = "Hmm, ciertamente es un tema muy complicado, pero para que un niño de tu edad entienda tanto... Eres una niña bastante increíble.",
  ui_story_32040401_73_dialog_content = "... ¿Ah?",
  ui_story_32040401_74_dialog_content = "Sin duda, no hay otro lugar en todo Astra tan pacífico y sagrado como Northland.",
  ui_story_32040401_75_dialog_content = "Pero diferentes personas de diferentes lugares tienen sus propias formas de vida. Simplemente quería que tú y tus amigos entendieran eso.",
  ui_story_32040401_76_dialog_content = "Al saber esto, estarán mejor equipados para forjarse un futuro más brillante.",
  ui_story_32040401_77_dialog_content = "E incluso después de aprender más sobre el mundo, está perfectamente bien si aún amas Northland más que cualquier otro lugar.",
  ui_story_32040401_78_dialog_content = "Oh... Mmm...",
  ui_story_32040401_79_dialog_content = "N-No solo me estás diciendo lo que quiero escuchar, ¿verdad...?",
  ui_story_32040401_80_dialog_content = "¡Jajaja! Dios mío, realmente eres un pequeño curioso.",
  ui_story_32040401_81_dialog_content = "De hecho, me recuerdas mucho a alguien que conozco...",
  ui_story_32040401_82_dialog_content = "Tengo una última cosa que deseo compartir contigo, niña. Eres libre de creer o no en mis palabras, siempre y cuando las pienses un poco.",
  ui_story_32040401_83_dialog_content = "Tu manera honesta y directa de hablar puede dar a los demás la impresión de que eres demasiado franco o incluso inmaduro.",
  ui_story_32040401_84_dialog_content = "Pero sé que ese no es el caso. Eres mucho más cuidadoso y considerado que muchos adultos, y tienes algo importante que deseas proteger.",
  ui_story_32040401_85_dialog_content = "Esta, a su vez, es la razón por la que no bajas la guardia tan fácilmente.",
  ui_story_32040401_86_dialog_content = "Tu naturaleza cautelosa y protectora es la raíz de tu supuesta descortesía.",
  ui_story_32040401_87_dialog_content = "Aún así, incluso alguien como usted necesita un confidente, alguien con quien pueda hablar libremente sobre sus preocupaciones sin temor a que lo desvíen.",
  ui_story_32040401_88_dialog_content = "De lo contrario, esas mismas preocupaciones seguirán acumulándose y eventualmente te convertirán en una persona miope e incluso hostil.",
  ui_story_32040401_89_dialog_content = "Puede pasar algún tiempo antes de que encuentre un confidente como este. Hasta entonces, ten en cuenta tus defectos y no dejes que te superen.",
  ui_story_32040401_90_dialog_content = "...",
  ui_story_32040401_91_dialog_content = "Lo siento... ¿Fue demasiado complicado para ti?",
  ui_story_32040401_92_dialog_content = "¡N-En absoluto! ¡Entiendo!",
  ui_story_32040401_93_dialog_content = "Aunque algunas de las palabras fueron un poco difíciles de entender... ¡Sigo pensando que tienes razón!",
  ui_story_32040401_94_dialog_content = "E-Entonces, ¿estaría bien si... si nos hiciéramos amigos? ¿Me escucharás y evitarás que me desvíe?",
  ui_story_32040401_95_dialog_content = "¿Yo?",
  ui_story_32040401_96_dialog_content = "¡Sí tú! ¡Eres la primera persona que me entiende tan bien!",
  ui_story_32040401_97_dialog_content = "Yo... Si no te importa, entonces sería un honor para mí.",
  ui_story_32040401_98_dialog_content = "¡Hurra!",
  ui_story_32040401_99_dialog_content = "Mi ayuda... ¿para guiar a los demás?",
  ui_story_32040401_100_dialog_content = "No estás obligado a tomar el té con las otras esposas nobles si no lo deseas. Joshua.",
  ui_story_32040401_101_dialog_content = "Próximamente se elegirá un nuevo gobernador. Para que ganes y establezcas tu prestigio, debo desempeñar el papel de una perfecta esposa noble.",
  ui_story_32040401_102_dialog_content = "Ahora no es el momento de hacer lo que deseo.",
  ui_story_32040401_103_dialog_content = "Pero Joshua, ¿qué cambiará si nos convertimos en los próximos gobernantes de Lumopolis satisfaciendo los caprichos de esos decrépitos aristócratas?",
  ui_story_32040401_104_dialog_content = "No seríamos más que marionetas de la nobleza, en ese caso.",
  ui_story_32040401_105_dialog_content = "Bien dicho, Daniel, pero los partidarios de tu padre ya se han puesto del lado de nosotros.",
  ui_story_32040401_106_dialog_content = "A esos centristas les importa un carajo la política, pero si no conseguimos su ayuda, ¿qué posibilidades tenemos de ganar?",
  ui_story_32040401_107_dialog_content = "Tenía la impresión de que estabas interpretando el papel de una perfecta esposa noble. ¿Por qué vuelves a mostrarme un lado tan hostil de ti mismo?",
  ui_story_32040401_108_dialog_content = "Lo siento, solo estaba...",
  ui_story_32040401_109_dialog_content = "Sé que estás preocupado por las elecciones.",
  ui_story_32040401_110_dialog_content = "Y en comparación con cuando nos conocimos, te has convertido en una persona mucho más amable y gentil... Alguien que también sonríe mucho más.",
  ui_story_32040401_111_dialog_content = "Es por eso que no quiero que vuelvas a ser la persona que una vez fuiste: alguien que debe usar un disfraz en todo momento para lograr un objetivo lejano.",
  ui_story_32040401_112_dialog_content = "Yo... simplemente no sé cómo proceder, especialmente cuando esas mujeres nobles cabeza hueca se ríen y ridiculizan a la gente de Lower Lumopolis.",
  ui_story_32040401_113_dialog_content = "Pero tampoco quiero perder su apoyo por esto.",
  ui_story_32040401_114_dialog_content = "Jajaja... Lo entiendo completamente. Ni uno solo de esos aristócratas piensa que puedo forjar mi propio camino.",
  ui_story_32040401_115_dialog_content = "Lo que estamos haciendo en este momento es explorar una nueva dirección, para que podamos ser dignos de guiar a otros hacia un futuro mejor. Debido a esto, no tenemos a nadie que nos guíe por el camino que tenemos por delante.",
  ui_story_32040401_116_dialog_content = "Pero al menos, nos tendremos el uno al otro.",
  ui_story_32040401_117_dialog_content = "Puede que no tengamos las respuestas correctas el uno para el otro cada vez, pero podemos compartir nuestras cargas unos con otros y evitar desviarnos.",
  ui_story_32040401_118_dialog_content = "Tienes razón. El camino hacia nuestro futuro ideal no será fácil de recorrer... Pero al menos, siempre tendré un compañero de confianza en quien confiar.",
  ui_story_32040401_119_dialog_content = "Suspiro... En momentos como estos, deberías referirte a nosotros como marido y mujer, o al menos como socios...",
  ui_story_32040401_120_dialog_content = "Ahí estás, señora Joshua! ¡Te he estado buscando por todas partes!",
  ui_story_32040401_121_dialog_content = "¡Oh! Lo siento, PlayerName, debo haberme perdido.",
  ui_story_32040401_122_dialog_content = "Estoy aliviado de ver que estás bien. Volvamos a Soroz, ¿de acuerdo?",
  ui_story_32040401_123_dialog_content = "PlayerName... May ¿Te hago una pregunta?",
  ui_story_32040401_124_dialog_content = "¿Eh? Seguro.",
  ui_story_32040401_125_dialog_content = "eres amigo de Carleen y Verónica, quiero decir, Mia... ¿Sí?",
  ui_story_32040401_126_dialog_content = "¿Podría decirme cómo les está yendo a los dos últimamente?",
  ui_story_32040401_127_dialog_content = "Como sus padres, ¿crees que Daniel y yo... Hicimos un buen trabajo al criarlos?",
  ui_story_32040401_128_option_content = "¡Por supuesto! Eres una persona tan amable.",
  ui_story_32040401_129_dialog_content = "¡Por supuesto que ustedes dos lo hicieron! Caballero Schwartz es una persona tan digna e inteligente, y usted es una de las personas más amables y gentiles que he conocido.",
  ui_story_32040401_130_dialog_content = "soy positivo Mia y Carleen aprendi mucho de los dos!",
  ui_story_32040401_131_dialog_content = "Ya entiendo, gracias.",
  ui_story_32040401_132_option_content = "No sé, pero estoy seguro de que hiciste lo mejor que pudiste.",
  ui_story_32040401_133_dialog_content = "Yo, eh... no soy Mia o Carleen, así que realmente no tengo derecho a juzgar su educación, ¿sabes?",
  ui_story_32040401_134_dialog_content = "Perfectamente cierto, sí.",
  ui_story_32040401_135_dialog_content = "Pero cuando veo lo que tú y el Señor Schwartz han pasado, creo que podría tener una idea.",
  ui_story_32040401_136_dialog_content = "Ustedes dos siempre han estado dispuestos a luchar por el bien de su familia y sus ideales... Que es algo que definitivamente aprendieron de ustedes.",
  ui_story_32040401_137_dialog_content = "Gracias, querido niño. Su afirmación es más significativa para mí que cualquiera de los halagos vacíos que alguna vez estuve acostumbrado a escuchar. Desde el fondo de mi corazón, gracias.",
  ui_story_32040401_138_dialog_content = "¡N-No tienes que ser tan cortés! Solo estaba diciendo lo que estaba en mi mente, ¡eso es todo!",
  ui_story_32040401_139_dialog_content = "Muy bien. Cambiemos de tema a algo más alegre.",
  ui_story_32040401_140_dialog_content = "¿Por qué no hablamos de nuestras últimas aventuras en el camino de regreso al Coloso?",
  ui_story_32040401_141_dialog_content = "Después de todo, ahora no soy más que un viajero solitario. Todo lo que tengo para ofrecer son mis experiencias de todo el mundo."
}
return config
